ee:message.ee:set-payload:
          %dw 2.0
output application/json
          var records = payload default []
---
records map ((account) -> {
            id: account.Id,
            globalId: account.SourceSystemIdentifier,
            externalIds: [{
              system: "Salesforce",
              value: account.SourceSystemIdentifier
            }],
            customerNumber: account.AccountNumber default null,
            party: {
              partyType: account.Type ,
              firstName: account.FirstName default null,
              lastName: account.LastName default null,
              taxId: account.taxId__c default null
            },
            status: account.Status__c default "Active"
          })

ee:variables.ee:set-variable:
          %dw 2.0
output application/java
var party = payload.party default {}
var sfId = payload.id default null
---
{
  sfId: sfId,
  account: {
    (Id: sfId) if sfId != null,
    (SourceSystemIdentifier: payload.globalId) if payload.globalId != null,
    AccountNumber: payload.customerNumber default null,
  //  Name: (party.firstName default "") ++ " " ++ //(party.lastName default ""),
    FirstName: party.firstName default null,
    LastName: party.lastName default null,
    taxId__c: party.taxId default null,
    Type: party.partyType default null,
    Status__c: payload.status default "Active"
  }
}

ee:message.ee:set-payload:
              %dw 2.0
output application/json
---
{
  error: {
    code: "BAD_REQUEST",
    message: payload.items[0].message default "Bad request",
    timestamp: now()
  }
}

          %dw 2.0
output application/json
var account = payload[0] default {}
---
{
  id: account.Id,
  globalId: account.SourceSystemIdentifier,
  externalIds: [{
    system: "Salesforce",
    value: account.SourceSystemIdentifier
  }],
  customerNumber: account.AccountNumber default null,
  party: {
    partyType: account.Type,
    firstName: account.FirstName default null,
    lastName: account.LastName default null,
    taxId: account.taxId__c default null
  },
  status: account.Status__c default "Active"
}
